// Rows from workflow_popularity (drop any empty-json items).
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && Object.keys(r).length > 0);

const isWorkflow = (p) => p === 'youtube' || p === 'forum';
const workflowRows = rows.filter((r) => isWorkflow(r.platform));
const trendRows = rows.filter((r) => r.platform === 'trends');

// Min-max normalize popularity_score to 0-100 within each platform separately.
// (reduce, not spread, so it scales to tens of thousands of rows)
function normalizeByPlatform(list) {
  const byPlat = {};
  for (const r of list) {
    const p = r.platform || 'unknown';
    (byPlat[p] = byPlat[p] || []).push(r);
  }
  const result = [];
  for (const plat of Object.keys(byPlat)) {
    const group = byPlat[plat];
    let min = Infinity;
    let max = -Infinity;
    for (const r of group) {
      const s = Number(r.popularity_score) || 0;
      if (s < min) min = s;
      if (s > max) max = s;
    }
    for (const r of group) {
      const s = Number(r.popularity_score) || 0;
      let norm;
      if (max === min) norm = 100; // all tied on their own scale
      else norm = ((s - min) / (max - min)) * 100;
      norm = Math.round(norm * 100) / 100;
      result.push(Object.assign({}, r, { __norm: norm }));
    }
  }
  return result;
}

const wfNorm = normalizeByPlatform(workflowRows);
const trNorm = normalizeByPlatform(trendRows);

const rankedAt = new Date().toISOString();
const out = [];

function emitRanked(list, category, scope, filterFn) {
  const subset = list.filter(filterFn);
  subset.sort(
    (a, b) =>
      b.__norm - a.__norm ||
      (Number(b.popularity_score) || 0) - (Number(a.popularity_score) || 0)
  );
  let pos = 0;
  for (const r of subset) {
    pos++;
    const sid = r.source_id || '';
    out.push({
      json: {
        rank_scope: scope,
        category: category,
        rank_position: pos,
        workflow: r.workflow || r.keyword || '',
        platform: r.platform || '',
        country: r.country || '',
        keyword: r.keyword || '',
        raw_popularity_score: Number(r.popularity_score) || 0,
        normalized_score: r.__norm,
        unified_score: r.__norm,
        views: Number(r.views) || 0,
        likes: Number(r.likes) || 0,
        comments: Number(r.comments) || 0,
        replies: Number(r.replies) || 0,
        contributors: Number(r.contributors) || 0,
        trend_interest: Number(r.trend_interest) || 0,
        trend_change_pct: Number(r.trend_change_pct) || 0,
        source_id: sid,
        source_url: r.source_url || '',
        channel_title: r.channel_title || '',
        ranking_key: scope + '|' + category + '|' + sid,
        ranked_at: rankedAt,
      },
    });
  }
}

// Individual workflows (YouTube + Forum), ranked together via normalized scores.
emitRanked(wfNorm, 'workflow', 'ALL', () => true);
emitRanked(wfNorm, 'workflow', 'US', (r) => r.country === 'US');
emitRanked(wfNorm, 'workflow', 'IN', (r) => r.country === 'IN');

// Google Trends keywords, ranked separately.
emitRanked(trNorm, 'trends', 'ALL', () => true);
emitRanked(trNorm, 'trends', 'US', (r) => r.country === 'US');
emitRanked(trNorm, 'trends', 'IN', (r) => r.country === 'IN');

return out;
